QS = [
(S, "What was the profession of Dr. Ruth Pfau, who worked for leprosy patients in Pakistan?", ["Engineer", "Teacher", "Physician (doctor)", "Lawyer"], 2, "Dr. Ruth Pfau was a German physician and nun who came to Pakistan in 1960. She devoted her life to fighting leprosy.", "She died in Karachi in 2017 and was given a state funeral.", [3500]),
(S, "What is a first person pronoun?", ["He", "I", "You", "They"], 1, "First person pronouns refer to the speaker. I, me, we and us are first person pronouns.", "You is second person, while he, she, it and they are third person.", [2848]),
(S, "Who was the first prophet of Islam?", ["Hazrat Nuh (AS)", "Hazrat Ibrahim (AS)", "Hazrat Musa (AS)", "Hazrat Adam (AS)"], 3, "Hazrat Adam (AS) was the first human being and the first prophet. The line of prophets ended with Hazrat Muhammad (SAW).", "Hazrat Nuh (AS) is often called the first messenger sent to a disbelieving people.", [4694]),
(S, "In which year was the C.R. Formula (Rajagopalachari Formula) proposed?", ["1940", "1944", "1946", "1942"], 1, "C. Rajagopalachari put forward the formula in 1944 to settle the Congress and Muslim League dispute. It was discussed in the Gandhi-Jinnah talks of September 1944.", "Quaid-e-Azam rejected it because it offered only a truncated Pakistan.", [249]),
(S, "What type of government did the 1956 Constitution of Pakistan provide?", ["Presidential", "Military", "Parliamentary", "Monarchy"], 2, "The 1956 Constitution created a parliamentary system with a one-house legislature. The Prime Minister held executive power, and the President was a constitutional head.", "Pakistan became an Islamic Republic under this constitution on 23 March 1956.", [2801, 349]),
(S, "Pakistan provides a sea route to the landlocked countries of which region?", ["Central Asia", "South America", "East Africa", "Western Europe"], 0, "Pakistan's ports, Karachi, Port Qasim and Gwadar, offer the shortest sea access for Afghanistan and the Central Asian states. These states have no coastline of their own.", "Afghanistan has long used Karachi port under the Afghan Transit Trade agreement.", [312, 2517]),
(S, "In which province is the Kachhi district located?", ["Balochistan", "Punjab", "Sindh", "Khyber Pakhtunkhwa"], 0, "Kachhi district, with its headquarters at Dhadar, lies in Balochistan. The Bolan Pass area is part of it.", "Kachhi plain is also known as the Kachhi-Bolan area.", [2216]),
(S, "In which province is the city of Rahim Yar Khan located?", ["Sindh", "Punjab", "Balochistan", "Khyber Pakhtunkhwa"], 1, "Rahim Yar Khan is a city and district in southern Punjab. It lies near the borders of Sindh and Balochistan.", "It is part of the Bahawalpur division.", [2217]),
(S, "How many states does India have?", ["25", "28", "29", "31"], 1, "India has 28 states and 8 union territories. Telangana became the 29th state in 2014, but Jammu and Kashmir became a union territory in 2019.", "Ladakh became a separate union territory in 2019.", [1878]),
(S, "In which constitution of Pakistan were Islamic provisions first included?", ["1962 Constitution", "1956 Constitution", "1973 Constitution", "Government of India Act 1935"], 1, "The 1956 Constitution was the first constitution of Pakistan and made the country an Islamic Republic. It included Islamic provisions.", "The Objectives Resolution of 1949 was made its preamble.", [2135, 526]),
(S, "Which team won the PSL trophy two times in a row?", ["Islamabad United", "Quetta Gladiators", "Lahore Qalandars", "Karachi Kings"], 2, "Lahore Qalandars won PSL 7 in 2022 and PSL 8 in 2023, back to back. No other team has won consecutive titles.", "Lahore Qalandars also won in 2025, and Peshawar Zalmi won PSL 11 in 2026.", [4319, 4320, 4321, 4776]),
(S, "In which year was PTCL (Pakistan Telecommunication Company Limited) established?", ["1947", "1985", "1996", "2005"], 2, "PTCL was formed in 1996 by taking over the telecom operations of the Pakistan Telegraph and Telephone Department. It was partly privatised in 2006.", "Etisalat of the UAE bought a controlling stake in 2006.", [2314]),
(S, "What does PTCL stand for?", ["Pakistan Telecommunication Company Limited", "Pakistan Telephone Corporation Limited", "Pakistan Transmission and Cable Limited", "Pakistan Telegraph Company Limited"], 0, "PTCL is the short form of Pakistan Telecommunication Company Limited. It is the country's largest telecom operator in fixed line services.", "It owns the Ufone mobile brand.", [3114]),
(S, "Who is the Education Minister of Punjab (Pakistan) at present?", ["Rana Sikandar Hayat", "Khawaja Salman Rafique", "Bilal Yasin", "Maryam Aurangzeb"], 0, "Rana Sikandar Hayat is the School Education Minister in the Punjab government, as reported in 2026. Maryam Nawaz is the Chief Minister.", "Ministers can change after a cabinet reshuffle.", [4516]),
(S, "Which is the largest district of Punjab (Pakistan) by area?", ["Lahore", "Rahim Yar Khan", "Bahawalpur", "Dera Ghazi Khan"], 2, "Bahawalpur district covers about 24,800 square km, the largest in Punjab. Rahim Yar Khan and Dera Ghazi Khan are smaller.", "Lahore is the largest district by population in Punjab.", [4057]),
(S, "In which constitutional amendment were Qadianis declared non-Muslim in Pakistan?", ["First Amendment", "Second Amendment", "Fourth Amendment", "Eighth Amendment"], 1, "The Second Amendment to the 1973 Constitution, passed in 1974, declared Qadianis (Ahmadis) non-Muslims. It was passed under Prime Minister Zulfikar Ali Bhutto.", "The amendment added clause 3 to Article 260.", [301]),
(S, "Under which article of the 1973 Constitution is the definition of a Muslim and non-Muslim given, as added by the Second Amendment?", ["Article 62", "Article 227", "Article 260", "Article 2"], 2, "The Second Amendment added clause 3 to Article 260 and defined who is a Muslim. Qadianis were thus declared non-Muslim.", "Article 2 declares Islam the State religion.", [808]),
(S, "On which date were the Qadianis declared non-Muslim in Pakistan?", ["7 September 1974", "14 August 1973", "23 March 1974", "5 July 1977"], 0, "The National Assembly passed the Second Amendment on 7 September 1974. It declared Qadianis non-Muslim.", "7 September is remembered in Pakistan as Khatm-e-Nubuwwat Day.", [4648]),
(S, "What is a quarter of 1/10 of 1/120?", ["1/4800", "1/1200", "1/480", "1/3000"], 0, "1/10 of 1/120 = 1/1200. A quarter of 1/1200 = 1/4800.", "Taking a quarter of a number means dividing it by 4.", [2859]),
(S, "What is a quarter of 1/10 of 1200?", ["120", "40", "30", "300"], 2, "1/10 of 1200 = 120. A quarter of 120 = 30.", "A quarter of 1200 is 300, so one tenth of that is also 30.", [2860]),
(S, "In which year was the Radcliffe Award announced?", ["1945", "1946", "1947", "1948"], 2, "The Radcliffe Boundary Commission award was announced on 17 August 1947, after independence. It fixed the Punjab and Bengal boundaries.", "Sir Cyril Radcliffe headed the commission.", [2276, 2315]),
]
